# Hard-caption condition in n10 requires explicit 'conical vortices' in caption.
J['n10_zh'][3]=('C','图注仅表面流型，未明确提锥形涡；命中条件要求图注明说')
assert len(J)==40 and all(len(v)==5 for v in J.values())
rows=list(csv.DictReader(source.open(newline='')))
assert len(rows)==200
counts=collections.Counter()
queue=[]
notes=['# 0152 冻结结果文字复判（不含图面）','', '仅使用 top5_all_candidates.csv 与 results_top5.md 的既有图注、题录和固定排名；没有重跑查询、改题或看图。A 为文字必要条件全部可证，B 为主题成立但图面条件未证，C 为文字明确不符或仅沾边。A/B 均非最终命中，图面正确与完整裁切由 Lead 判。','']
for qid in questions:
 for mode in ('zh','en'):
  block=qid+'_'+mode
  rr=[x for x in rows if x['id']==qid and x['mode']==mode]
  assert len(rr)==5 and [int(x['rank']) for x in rr]==list(range(1,6))
  notes += [f'## {block}', '', f'冻结 hit：{questions[qid]["hit"]}', '', '| 排名 | 图号 | 档位 | 图注与题录的文字判据／待确认 |','|---:|---|:---:|---|']
  ab=[]
  for x,(grade,reason) in zip(rr,J[block]):
   counts[grade]+=1
   notes.append(f'| {x["rank"]} | `{x["fig_id"]}` | {grade} | {reason} |')
   if grade in 'AB':
    ab.append(f'{x["rank"]}=`{x["fig_id"]}`({grade})')
    queue.append({'block':block,'rank':x['rank'],'fig_id':x['fig_id'],'档位':grade,'待看图确认的条件':reason if grade=='B' else '核图是否所述散点图、坐标与数据一致，以及是否配错或截断'})
  notes += ['', 'A/B 候选：'+('；'.join(ab) if ab else '无'), '']
(p/'TEXT_JUDGMENT.md').write_text('\n'.join(notes)+'\n')
with (p/'VISUAL_QUEUE.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['block','rank','fig_id','档位','待看图确认的条件']);w.writeheader();w.writerows(queue)
print('blocks',len(J),'rows',len(rows),'grades',dict(counts),'visual_queue',len(queue),'A/B blocks',sum(any(g in 'AB' for g,_ in v) for v in J.values()))
